      "path": "cli/src/guard.ts",
      "content": "/**\n * The guard on the model channel: this gateway is the one thing every request passes through, side\n * requests included, whichever harness sent it. Outbound, secrets become placeholders. Inbound, tool\n * calls are judged on those placeholders, and only what is allowed gets the real value back.\n */\nimport { type CompiledRuleset } from \"./redaction/ruleset.js\";\nimport { maskRequest } from \"./redaction/mask.js\";\nimport { restore, UNRESTORABLE_NOTICE } from \"./redaction/restore.js\";\nimport { restoreResponseBody } from \"./redaction/protocol.js\";\nimport { SessionMap } from \"./redaction/session.js\";\nimport { compiledRules } from \"./secrets/mask.js\";\nimport { createStreamGuard, type Refusals, type StreamCall } from \"./guard-stream.js\";\nimport type { LlmProtocol } from \"./model.js\";\nimport type { LocalRuntime } from \"./runtime.js\";\nimport { callsIn, entriesFromMessages, type TranscriptEntry } from \"./transcript.js\";\n\n/**\n * Well above what a plugin in the same agent mints from 1. One value must never have two meanings\n * on one wire, and a plugin and this gateway can both be in the path.\n */\nconst FIRST_TOKEN = 5_000_000;\n/** A value past this is masked for good: it cannot be restored. Better than a value that leaves. */\nconst MAX_VALUES = 4096;\n\nexport interface GuardedRequest {\n  body: Record<string, any>;\n  map: SessionMap;\n  history: TranscriptEntry[];\n  agentType: string;\n}\n\nexport class ModelChannelGuard {\n  private readonly maps = new Map<string, SessionMap>();\n  private counter = FIRST_TOKEN;\n  private readonly rules: CompiledRuleset = compiledRules();\n\n  constructor(private readonly runtime: LocalRuntime) {}\n\n  /** One map per agent, so a value keeps its placeholder across every conversation. */\n  private mapFor(agentType: string): SessionMap {\n    let map = this.maps.get(agentType);\n    if (!map) {\n      map = new SessionMap(agentType, { bound: MAX_VALUES, allocate: () => ++this.counter });\n      this.maps.set(agentType, map);\n    }\n    return map;\n  }\n\n  outbound(agentType: string, parsed: Record<string, any>): GuardedRequest {\n    const map = this.mapFor(agentType);\n    const { value: body } = maskRequest(parsed, map, this.rules);\n    return { body, map, agentType, history: entriesFromMessages(body.messages ?? body.input) };\n  }\n\n  /** Every call answered. A failure inside must not become an allow: it fails to the rules' caller as a refusal. */\n  private async refusals(request: GuardedRequest, calls: StreamCall[]): Promise<Refusals> {\n    const refused: Refusals = new Map();\n    if (calls.length === 0) return refused;\n    const judged = await this.runtime.judgeCalls(calls, [...request.history], request.agentType, request.agentType);\n    judged.forEach((answer, i) => {\n      const call = calls[i]!;\n      if (answer.refused) refused.set(call.path, answer.refused.notice);\n    });\n    // A placeholder nothing here can answer, after a restart for instance. Running with it would hand\n    // a tool a word that looks like a value.\n    for (const call of calls) {\n      const [token] = restore(JSON.stringify(call.args), request.map).unresolved;\n      if (token && !refused.has(call.path)) refused.set(call.path, UNRESTORABLE_NOTICE(token));\n    }\n    return refused;\n  }\n\n  whole(request: GuardedRequest, protocol: LlmProtocol, reply: string): Promise<string> {\n    return this.renderWhole(request, protocol, reply).catch((error) => JSON.stringify({ error: { message: `openguardrails could not judge this reply: ${String(error)}`, type: \"openguardrails_internal\" } }));\n  }\n\n  private async renderWhole(request: GuardedRequest, protocol: LlmProtocol, reply: string): Promise<string> {\n    let parsed: any;\n    try {\n      parsed = JSON.parse(reply);\n    } catch {\n      return reply;\n    }\n    const calls = callsIn(protocol, parsed);\n    const refused = await this.refusals(request, calls);\n    let out = reply;\n    const told = this.runtime.takeQuotaNotice();\n    const notice = [...new Set(refused.values()), ...(told ? [told] : [])].join(\" \");\n    if (notice) {\n      if (protocol === \"openai.chat\") {\n        const message = parsed.choices?.[0]?.message ?? {};\n        message.tool_calls = (message.tool_calls ?? []).filter((_: unknown, i: number) => !refused.has(`payload.choices.0.message.tool_calls.${i}`));\n        message.content = [message.content, notice].filter(Boolean).join(\"\\n\\n\");\n        if (message.tool_calls.length === 0) {\n          delete message.tool_calls;\n          parsed.choices[0].finish_reason = \"stop\";\n        }\n      } else if (protocol === \"anthropic.messages\") {\n        parsed.content = (parsed.content ?? []).filter((_: unknown, i: number) => !refused.has(`payload.content.${i}`));\n        parsed.content.push({ type: \"text\", text: notice });\n        if (!parsed.content.some((block: any) => block.type === \"tool_use\")) parsed.stop_reason = \"end_turn\";\n      } else {\n        parsed.output = (parsed.output ?? []).filter((_: unknown, i: number) => !refused.has(`payload.output.${i}`));\n        parsed.output.push({ type: \"message\", role: \"assistant\", content: [{ type: \"output_text\", text: notice }] });\n      }\n      out = JSON.stringify(parsed);\n    }\n    return restoreResponseBody(protocol, out, request.map)?.body ?? out;\n  }\n\n  stream(request: GuardedRequest, protocol: LlmProtocol, write: (text: string) => void) {\n    return createStreamGuard({\n      protocol,\n      map: request.map,\n      write,\n      notice: () => this.runtime.takeQuotaNotice(),\n      judge: (calls) =>\n        this.refusals(request, calls).catch((error) => {\n          // No answer is not an allow: every call is refused, and the agent is told it was a fault.\n          const notice = `This action was NOT executed: openguardrails failed while judging it (${String(error)}). Tell the user.`;\n          return new Map(calls.map((call) => [call.path, notice]));\n        }),\n    });\n  }\n}\n"
    },
    {
      "path": "cli/src/policy.ts",
      "content": "/** What a run may touch, as sandbox-runtime configuration. */\nimport { realpathSync } from \"node:fs\";\nimport { homedir, tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport type { SandboxRuntimeConfig } from \"@anthropic-ai/sandbox-runtime\";\n\nexport interface PolicyOptions {\n  cwd: string;\n  allowHosts: string[];\n  denyHosts: string[];\n  allowRead: string[];\n  allowWrite: string[];\n  allowLocalBinding?: boolean;\n}\n\n/** Where credentials live. A starting point rather than a boundary: an unlisted path stays readable. */\nconst CREDENTIAL_PATHS = [\n  // Its own keys, and shell startup files, where people export theirs.\n  \".openguardrails\", \".zshrc\", \".zshenv\", \".zprofile\", \".bashrc\", \".bash_profile\", \".profile\",\n  \".ssh\", \".aws\", \".azure\", \".oci\", \".kube\", \".gnupg\", \".config/gcloud\", \".config/gh\",\n  \".docker/config.json\", \".netrc\", \".npmrc\", \".pypirc\", \".pgpass\", \".git-credentials\", \".boto\", \".my.cnf\",\n];\n\n/** Where the agents this is built for keep their own state; without these they fail to start. */\nconst AGENT_STATE_PATHS = [\n  \".claude\", \".claude.json\", \".codex\", \".gemini\", \".pi\", \".dsh\", \".hermes\", \".openclaw\", \".aider\",\n  \".config/opencode\", \".local/share/opencode\", \".local/state\", \".cache\", \".npm\", \".bun\", \"Library/Caches\",\n];\n\n/** macOS /tmp is a symlink, and sandbox-runtime silently drops a symlink that short as out of bounds. */\nconst real = (path: string) => {\n  try {\n    return realpathSync(path);\n  } catch {\n    return path;\n  }\n};\n\n/**\n * This machine and the cloud metadata endpoints: what a poisoned model probes first, and never a\n * destination an agent found by itself. Allow one by name with --allow-host. Private LAN ranges\n * are not on this list, because intranet services are ordinary work.\n */\nexport function isLocalTarget(host: string): boolean {\n  const name = host.replace(/^\\[|\\]$/g, \"\").replace(/\\.$/, \"\").toLowerCase();\n  if (name === \"localhost\" || name.endsWith(\".localhost\")) return true;\n  if (name === \"::1\" || name === \"::\" || name.startsWith(\"fe80:\") || name.startsWith(\"fd00:ec2:\")) return true;\n  if (name.startsWith(\"::ffff:\")) return isLocalTarget(name.slice(7));\n  return /^(127|0|169\\.254)\\.[\\d.]+$/.test(name) || [\"100.100.100.200\", \"168.63.129.16\", \"192.0.0.192\", \"metadata.google.internal\"].includes(name);\n}\n\n/**\n * Opens one loopback port on macOS. Agents commonly refuse to proxy loopback addresses (dsh does,\n * by design), so the gateway must be reachable directly, and sandbox-runtime's only switch for\n * that opens every local port, browser debugging ports included.\n */\nexport function openLoopbackPort(wrapped: string, port: number): string {\n  const rule = /\\(allow network-outbound \\(remote ip \"localhost:\\d+\"\\)\\)/;\n  if (!rule.test(wrapped)) throw new Error(\"this sandbox-runtime version has an unexpected profile; openguardrails cannot open the gateway port\");\n  return wrapped.replace(rule, (match) => `${match}\\n(allow network-outbound (remote ip \"localhost:${port}\"))`);\n}\n\nexport function buildPolicy(options: PolicyOptions): SandboxRuntimeConfig {\n  const home = homedir();\n  const inHome = (path: string) => join(home, path);\n  return {\n    network: {\n      // Empty on purpose: every other host reaches the ask callback, which is where a run in\n      // observe mode lets it through and writes it down.\n      allowedDomains: options.allowHosts,\n      deniedDomains: options.denyHosts,\n      ...(options.allowLocalBinding ? { allowLocalBinding: true } : {}),\n    },\n    filesystem: {\n      denyRead: [\n        ...CREDENTIAL_PATHS.map(inHome),\n        join(options.cwd, \"**/.env\"),\n        join(options.cwd, \"**/.env.*\"),\n      ],\n      allowRead: options.allowRead,\n      allowWrite: [options.cwd, real(tmpdir()), real(\"/tmp\"), ...AGENT_STATE_PATHS.map(inHome), ...options.allowWrite],\n      denyWrite: [],\n    },\n  };\n}\n"
    },
    {
      "path": "cli/src/run.ts",
      "content": "/** `openguardrails run`: start a command in the sandbox and record what its whole process tree does. */\nimport { spawn } from \"node:child_process\";\nimport { randomBytes } from \"node:crypto\";\nimport zlib from \"node:zlib\";\nimport { SandboxManager, type FilterRequestCallback, type SandboxRuntimeConfig } from \"@anthropic-ai/sandbox-runtime\";\nimport { airsTarget, guardEvent, report } from \"./airs.js\";\nimport { keyEnvNames, loadConfig, looseConfigWarning } from \"./config.js\";\nimport { Correlator } from \"./correlate.js\";\nimport { fileObservation, type Observation } from \"./exec.js\";\nimport { classifyModelRequest, harnessFrom, hostsIn, toolCallsIn, toolResultIdsIn, type LlmProtocol } from \"./model.js\";\nimport { buildPolicy, isLocalTarget, openLoopbackPort, type PolicyOptions } from \"./policy.js\";\nimport { Recorder, safePath } from \"./record.js\";\nimport { ensureGateway, gatewayPort, gatewayToken, hydrateEnv } from \"./serve.js\";\n\nexport interface RunOptions extends Omit<PolicyOptions, \"cwd\"> {\n  enforce: boolean;\n  allowLocalBinding?: boolean;\n  command: string[];\n}\n\n/** A connection waits this long for the tool call that names it, which only arrives with the next model request. */\nconst GRACE_MS = 120_000;\n\nfunction decode(bytes: Buffer, encoding: string): Buffer {\n  switch (encoding) {\n    case \"gzip\": return zlib.gunzipSync(bytes);\n    case \"br\": return zlib.brotliDecompressSync(bytes);\n    case \"deflate\": return zlib.inflateSync(bytes);\n    case \"zstd\": return zlib.zstdDecompressSync(bytes);\n    default: return bytes;\n  }\n}\n\nconst quote = (arg: string) => (/^[\\w@%+=:,./-]+$/.test(arg) ? arg : `'${arg.replaceAll(\"'\", `'\\\\''`)}'`);\n\nexport async function run(options: RunOptions): Promise<number> {\n  const runId = `${new Date().toISOString().replace(/[-:.]/g, \"\").slice(0, 15)}-${randomBytes(3).toString(\"hex\")}`;\n  const recorder = new Recorder(runId);\n  const correlator = new Correlator();\n  const settings = loadConfig();\n  hydrateEnv(settings);\n  const warning = looseConfigWarning(settings);\n  if (warning) process.stderr.write(`[openguardrails] ${warning}\\n`);\n  const airs = airsTarget(settings);\n  // The gateway reports what passes through it; reporting it here too would judge each call twice.\n  const ownPort = settings.gateway ? gatewayPort(settings) : null;\n  if (settings.gateway) await ensureGateway(settings);\n  const seenCalls = new Set<string>();\n  const command = options.command.map(quote).join(\" \");\n\n  // Set once a tool result answers a call this run never saw. From then on \"no tool call named it\"\n  // cannot be claimed, because a call we cannot see may have named it.\n  const blindTo = new Set<string>();\n\n  const flush = (final = false) => {\n    for (const found of correlator.flush(Date.now(), GRACE_MS, final)) {\n      const { bytesUp, ...rest } = found;\n      const verified = blindTo.size === 0;\n      recorder.write(verified ? \"undeclared\" : \"unverified\", { ...rest, bytes_up: bytesUp, blind_to: [...blindTo] });\n      const label = verified ? \"undeclared destination\" : \"unverified destination\";\n      process.stderr.write(`[openguardrails] ${label}: ${found.host} (${found.methods.join(\"/\")}, ${bytesUp}B up)\\n`);\n    }\n  };\n\n  // Calls that went straight to the gateway never pass this process's proxy, so they are asked for.\n  const startedAt = Date.now();\n  let lastActivity = startedAt;\n  let servedAtStart: number | null = null;\n  const syncGateway = async () => {\n    if (ownPort === null) return;\n    try {\n      const response = await fetch(`http://127.0.0.1:${ownPort}/__ogr/activity?since=${lastActivity}`, { headers: { \"x-openguardrails-token\": gatewayToken() }, signal: AbortSignal.timeout(2000) });\n      const seen = (await response.json()) as { served: number; blind_to: string[]; calls: Array<{ t: number; agent: string; name: string; hosts: string[] }> };\n      servedAtStart ??= seen.served;\n      if (seen.served > servedAtStart) correlator.noteModelHost(\"127.0.0.1\");\n      for (const name of seen.blind_to) blindTo.add(name);\n      for (const call of seen.calls) {\n        lastActivity = Math.max(lastActivity, call.t);\n        correlator.noteDeclared(call.hosts);\n        recorder.write(\"tool_call\", { harness: call.agent, name: call.name, hosts: call.hosts });\n      }\n    } catch {\n      // Judged on what is known; the final pass tries again.\n    }\n  };\n\n  // The sandbox's half of the story, sent to the gateway, which knows which tool call was open.\n  let outbox: Observation[] = [];\n  const sendObservations = async () => {\n    if (ownPort === null || outbox.length === 0) return;\n    const batch = outbox;\n    outbox = [];\n    await fetch(`http://127.0.0.1:${ownPort}/__ogr/observe`, {\n      method: \"POST\",\n      headers: { \"x-openguardrails-token\": gatewayToken() },\n      body: JSON.stringify(batch),\n      signal: AbortSignal.timeout(2000),\n    }).catch(() => undefined);\n  };\n  const observeTimer = setInterval(() => void sendObservations(), 250);\n\n  const readModelRequest = async (request: Request, host: string, protocol: LlmProtocol, viaGateway: boolean) => {\n    const harness = harnessFrom(request.headers.get(\"user-agent\") ?? \"\");\n    let body: any;\n    try {\n      const raw = Buffer.from(await new Response(request.body).arrayBuffer());\n      body = JSON.parse(decode(raw, request.headers.get(\"content-encoding\") ?? \"\").toString(\"utf8\"));\n    } catch (error) {\n      recorder.write(\"model\", { harness, host, protocol, unparsed: String(error) });\n      return;\n    }\n    recorder.write(\"model\", { harness, host, protocol, model: body?.model });\n    for (const call of toolCallsIn(protocol, body)) {\n      if (seenCalls.has(call.id)) continue;\n      seenCalls.add(call.id);\n      const hosts = hostsIn(call.args);\n      correlator.noteDeclared(hosts);\n      recorder.write(\"tool_call\", { harness, name: call.name, hosts });\n    }\n    if (toolResultIdsIn(protocol, body).some((id) => !seenCalls.has(id))) blindTo.add(harness);\n    flush();\n    if (airs && !viaGateway) {\n      report(airs, guardEvent(runId, harness, protocol, body, airs.agentId))\n        .then((verdict) => recorder.write(\"verdict\", verdict))\n        .catch((error) => recorder.write(\"verdict\", { decision: \"unjudged\", findings: 0, error: String(error) }));\n    }\n  };\n\n  // Answers straight away and reads the body beside the forward, so recording never delays a request.\n  const filterRequest: FilterRequestCallback = async (request, info) => {\n    const url = new URL(request.url);\n    const host = info?.target?.host ?? url.hostname;\n    const bytes = Number(request.headers.get(\"content-length\") ?? 0);\n    const protocol = classifyModelRequest(request.method, url.pathname);\n    const ownTraffic = ownPort !== null && host === \"127.0.0.1\" && info?.target?.port === ownPort;\n    if (!protocol && !ownTraffic) outbox.push({ t: Date.now(), kind: \"network\", target: `${host}:${info?.target?.port ?? (url.protocol === \"https:\" ? 443 : 80)}`, action: request.method, ...(bytes ? { bytes } : {}) });\n    if (protocol) {\n      correlator.noteModelHost(host);\n      void readModelRequest(request, host, protocol, ownPort !== null && host === \"127.0.0.1\" && info?.target?.port === ownPort);\n    } else {\n      correlator.noteConnection(host, request.method, bytes, Date.now());\n      recorder.write(\"request\", { method: request.method, host, path: safePath(url.pathname), bytes });\n    }\n    return { action: \"allow\" };\n  };\n\n  const config: SandboxRuntimeConfig = {\n    ...buildPolicy({\n      cwd: process.cwd(),\n      allowHosts: [\n        ...options.allowHosts,\n        ...(settings.sandbox?.allowHosts ?? []),\n        ...(ownPort !== null ? [`127.0.0.1:${ownPort}`] : []),\n      ],\n      denyHosts: [...options.denyHosts, ...(settings.sandbox?.denyHosts ?? [])],\n      allowRead: [...options.allowRead, ...(settings.sandbox?.allowRead ?? [])],\n      allowWrite: [...options.allowWrite, ...(settings.sandbox?.allowWrite ?? [])],\n      allowLocalBinding: options.allowLocalBinding || settings.sandbox?.allowLocalBinding === true,\n    }),\n  };\n  config.network = { ...config.network, tlsTerminate: {}, filterRequest } as typeof config.network;\n\n  const deps = SandboxManager.checkDependencies();\n  if (deps.errors.length > 0) {\n    process.stderr.write(`[openguardrails] cannot start: ${deps.errors.join(\"; \")}\\n`);\n    return 127;\n  }\n\n  const ask = async ({ host, port }: { host: string; port?: number | undefined }) => {\n    const local = isLocalTarget(host);\n    recorder.write(\"connect\", { host, port, allowed: !options.enforce && !local });\n    if (local || options.enforce) outbox.push({ t: Date.now(), kind: \"network\", target: `${host}:${port}`, denied: true });\n    if (local) return { allow: false as const, reason: `openguardrails: ${host} is this machine or a metadata endpoint. Allow it with --allow-host ${host}:${port}` };\n    if (!options.enforce) return true;\n    return { allow: false as const, reason: `openguardrails: ${host} is not allowed. Add it with --allow-host ${host}` };\n  };\n  // The third argument turns on the violation monitor; denied reads are not reported without it.\n  await SandboxManager.initialize(config, ask, true);\n\n  const seenViolations = new Set<string>();\n  const unsubscribe = SandboxManager.getSandboxViolationStore().subscribe((violations) => {\n    for (const violation of violations) {\n      const key = `${violation.timestamp.getTime()}:${violation.line}`;\n      if (seenViolations.has(key)) continue;\n      seenViolations.add(key);\n      // macOS reports every process's routine system probes; only files and network mean anything here.\n      if (/deny\\S* (sysctl|system-info|mach-|iokit|ipc-|process-info)/.test(violation.line)) continue;\n      recorder.write(\"violation\", { line: violation.line });\n      const file = fileObservation(violation.line, violation.timestamp.getTime());\n      if (file) outbox.push(file);\n    }\n  });\n\n  recorder.write(\"start\", { mode: options.enforce ? \"enforce\" : \"observe\", command: options.command[0], run: runId });\n  // sandbox-runtime exempts loopback and private ranges from the proxy, and those clients then fail\n  // inside the sandbox. A local vLLM is what this tool exists to see, so everything goes through it.\n  // NODE_USE_ENV_PROXY makes Node's own fetch honour the proxy; the pinned release does not set it.\n  let wrapped = await SandboxManager.wrapWithSandbox(`NO_PROXY= no_proxy= NODE_USE_ENV_PROXY=1 ${command}`, undefined, undefined, undefined, {\n    commandId: runId,\n    commandText: command,\n  });\n  if (ownPort !== null && process.platform === \"darwin\") wrapped = openLoopbackPort(wrapped, ownPort);\n  const childEnv = { ...process.env };\n  for (const name of keyEnvNames(settings)) delete childEnv[name];\n  const child = spawn(wrapped, { shell: true, stdio: \"inherit\", env: childEnv });\n  for (const signal of [\"SIGINT\", \"SIGTERM\"] as const) process.on(signal, () => child.kill(signal));\n  await syncGateway();\n  const syncTimer = setInterval(() => void syncGateway().then(() => flush()), 15_000);\n  const code = await new Promise<number>((resolve) => {\n    child.on(\"error\", () => resolve(127));\n    child.on(\"exit\", (exitCode, signal) => resolve(exitCode ?? (signal ? 128 : 1)));\n  });\n\n  // The macOS violation monitor reads an asynchronous system log, and body reads may be in flight.\n  await new Promise((resolve) => setTimeout(resolve, 1500));\n  clearInterval(syncTimer);\n  clearInterval(observeTimer);\n  await sendObservations();\n  await syncGateway();\n  flush(true);\n  recorder.write(\"exit\", { code });\n  unsubscribe();\n  await SandboxManager.reset();\n  process.stderr.write(`[openguardrails] run ${runId} recorded. See: openguardrails log ${runId}\\n`);\n  return code;\n}\n"
    },
    {
      "path": "cli/src/runtime.ts",
      "content": "/**\n * The OGR Runtime API on this machine. Every agent plugin already speaks `/v1/evaluate`, so pointing\n * `OGR_RUNTIME_URL` here gives each of them the local rules and the model with no change to its\n * wire, and pointing it at an enterprise AIRS later is the same setting.\n *\n * Only a step/response can be refused here: it is where tool calls exist. A step/request is kept\n * for its conversation, which is the context the model will need.\n */\nimport { randomUUID } from \"node:crypto\";\nimport { appendFileSync, mkdirSync } from \"node:fs\";\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\nimport { join } from \"node:path\";\nimport { homeDir, type Config } from \"./config.js\";\nimport { decideTool } from \"./decide.js\";\nimport { judge, ModelUnavailable, modelTarget, type Judgement, type ModelTarget } from \"./model-api.js\";\nimport { loadRuleset } from \"./secrets/mask.js\";\nimport { shellLine } from \"./tools.js\";\nimport { buildTranscript, callsIn, entriesFromMessages, type NormalCall, type TranscriptEntry } from \"./transcript.js\";\n\nexport const PROVIDER = \"openguardrails-local\";\nconst MAX_SESSIONS = 200;\nconst MAX_ENTRIES_KEPT = 512;\n/**\n * Hermes reports a shell command twice: as the tool call and again as the real argv at execution.\n * Both must be enforced, but one action is one model call, and a person pays for model calls.\n */\nconst REPEAT_WINDOW_MS = 10_000;\n\ninterface Finding {\n  category: string;\n  severity: \"low\" | \"medium\" | \"high\" | \"critical\";\n  path: string;\n  detector: string;\n  subject: string;\n}\n\nexport interface CallAnswer {\n  refused?: { category: string; severity: Finding[\"severity\"]; detector: string; notice: string };\n  unjudged?: boolean;\n}\n\nexport interface Verdict {\n  event_id: string;\n  provider: string;\n  decision: \"allow\" | \"block\";\n  latency_ms: number;\n  findings?: Finding[];\n  unjudged?: string[];\n  continuation?: { style: \"drop_calls\"; paths: string[]; notice: string };\n}\n\n/** Never holds an argument, a command or a message: what ran is not what this file is for. */\nfunction logDecision(fields: Record<string, unknown>): void {\n  try {\n    mkdirSync(homeDir(), { recursive: true, mode: 0o700 });\n    appendFileSync(join(homeDir(), \"decisions.ndjson\"), `${JSON.stringify({ t: new Date().toISOString(), ...fields })}\\n`, { mode: 0o600 });\n  } catch {\n    // A full disk must not turn into a refused or an allowed tool call.\n  }\n}\n\n/** Exactly what left this machine, so a person can check. Already masked. */\nfunction logSent(request: unknown): void {\n  try {\n    appendFileSync(join(homeDir(), \"model-requests.ndjson\"), `${JSON.stringify({ t: new Date().toISOString(), request })}\\n`, { mode: 0o600 });\n  } catch {\n    // As above.\n  }\n}\n\nconst RULE_NOTICE = (reason: string) =>\n  `This action was refused by a local safety rule and was NOT executed. Reason: ${reason}. Tell the user what you were trying to do, or reach the goal another way. Do not retry this action in a different form.`;\nconst MODEL_NOTICE = (reason: string) =>\n  `This action was refused as unsafe and was NOT executed. Reason: ${reason}. Reach the user's goal another way, or tell the user. Do not retry this action in a different form.`;\nconst DECISION_NOTICE = (reason: string) =>\n  `This action was NOT executed because it needs the user's own decision: ${reason}. Ask the user directly, and try again only after they answer in this conversation.`;\n\nconst UNAVAILABLE_NOTICE =\n  \"This action was NOT executed because the safety check could not answer just now. This is not a finding that it is unsafe. Try the same action once more. If it keeps failing, tell the user.\";\nconst QUOTA_NOTICE_EVERY_MS = 24 * 60 * 60 * 1000;\nconst QUOTA_NOTICE = (quota: { claim_url?: string; upgrade_url?: string }) =>\n  `OpenGuardrails: the free model quota for today is used up, so actions the local rules cannot decide are not being judged. Please tell the user: they can raise the quota at ${quota.claim_url ?? quota.upgrade_url ?? \"https://openguardrails.com\"}`;\n\nexport class LocalRuntime {\n  private readonly sessions = new Map<string, TranscriptEntry[]>();\n  /** When the person was last told the quota ran out. Telling them on every call would teach them to ignore it. */\n  private quotaToldAt = 0;\n  private quotaPending: string | null = null;\n  private readonly recent = new Map<string, { at: number; judgement: Judgement }>();\n  private readonly model: ModelTarget | null;\n  private readonly workspaces: string[];\n  private readonly failOpen: boolean;\n\n  constructor(config: Config, env = process.env) {\n    this.model = modelTarget(config, env);\n    this.workspaces = config.workspaces ?? [];\n    this.failOpen = config.model?.failMode === \"open\";\n  }\n\n  private remember(key: string, entries: TranscriptEntry[]): void {\n    this.sessions.delete(key);\n    this.sessions.set(key, entries.slice(-MAX_ENTRIES_KEPT));\n    if (this.sessions.size > MAX_SESSIONS) this.sessions.delete(this.sessions.keys().next().value as string);\n  }\n\n  private async judgeOnce(key: string, request: { transcript: TranscriptEntry[]; environment: { agent_type: string; workspaces: string[] } }): Promise<Judgement> {\n    const now = Date.now();\n    for (const [old, entry] of this.recent) if (now - entry.at > REPEAT_WINDOW_MS) this.recent.delete(old);\n    const seen = this.recent.get(key);\n    if (seen) return seen.judgement;\n    logSent(request);\n    const judgement = await judge(this.model!, request);\n    this.recent.set(key, { at: now, judgement });\n    return judgement;\n  }\n\n  /** A message for the person, handed out once. */\n  takeQuotaNotice(): string | null {\n    const notice = this.quotaPending;\n    this.quotaPending = null;\n    return notice;\n  }\n\n  /** One answer per call, in order. `history` grows as the calls are judged. */\n  async judgeCalls(calls: NormalCall[], history: TranscriptEntry[], agentType: string, session: string): Promise<CallAnswer[]> {\n    const answers: CallAnswer[] = [];\n    for (const call of calls) {\n      const answer: CallAnswer = {};\n      const refuse = (category: string, severity: Finding[\"severity\"], detector: string, notice: string) => {\n        answer.refused = { category, severity, detector, notice };\n      };\n      const local = decideTool(call, { workspaces: this.workspaces });\n      const record = (layer: string, decision: string, reason: string, extra: Record<string, unknown> = {}) =>\n        logDecision({ agent: agentType, tool: call.name, layer, decision, reason, ...extra });\n      if (local.verdict === \"allow\") {\n        record(\"rules\", \"allow\", local.reason);\n      } else if (local.verdict === \"deny\") {\n        record(\"rules\", \"deny\", local.reason);\n        refuse(\"security.malicious_command\", \"critical\", \"local-rules\", RULE_NOTICE(local.reason));\n      } else if (!this.model) {\n        // No model means no auto mode: the action goes on to the harness's own permission check,\n        // and it is reported as not judged. Nothing here claims it was looked at.\n        record(\"none\", \"unjudged\", local.reason);\n        answer.unjudged = true;\n      } else {\n        const transcript = buildTranscript(history, call);\n        const request = { transcript, environment: { agent_type: agentType, workspaces: this.workspaces } };\n        // Keyed on what would run, not on the tool's name: `terminal` and `bash` are one action.\n        const key = `${session}\\n${JSON.stringify(shellLine(call.args) ?? [call.name, call.args])}`;\n        let judgement: Judgement | null = null;\n        try {\n          judgement = await this.judgeOnce(key, request);\n        } catch (error) {\n          const quota = error instanceof ModelUnavailable ? error.quota : undefined;\n          record(\"model\", quota || this.failOpen ? \"unjudged\" : \"deny\", String((error as Error).message), quota ? { claim_url: quota.claim_url } : {});\n          // Someone who turned the model on is relying on it, so a passing failure must not switch it off.\n          // A used-up quota is a known state with a person told about it, and it must not stop all work.\n          if (!quota && !this.failOpen) refuse(\"x.ogr.unjudged\", \"low\", \"model\", UNAVAILABLE_NOTICE);\n          else answer.unjudged = true;\n          if (quota && Date.now() - this.quotaToldAt > QUOTA_NOTICE_EVERY_MS) {\n            this.quotaToldAt = Date.now();\n            this.quotaPending = QUOTA_NOTICE(quota);\n            process.stderr.write(`[openguardrails] ${this.quotaPending}\\n`);\n          }\n        }\n        if (judgement?.decision === \"allow\") {\n          record(\"model\", \"allow\", local.reason);\n        } else if (judgement?.decision === \"block\") {\n          const reason = judgement.reason ?? judgement.category ?? \"the model judged this action unsafe\";\n          record(\"model\", \"block\", reason, { category: judgement.category });\n          refuse(judgement.category ?? \"security.unsafe_action\", judgement.severity ?? \"high\", \"model\", MODEL_NOTICE(reason));\n        } else if (judgement?.decision === \"needs_decision\") {\n          const reason = judgement.reason ?? \"this is the user's decision\";\n          record(\"model\", \"needs_decision\", reason);\n          refuse(\"x.ogr.needs_decision\", \"low\", \"model\", DECISION_NOTICE(reason));\n        }\n      }\n      answers.push(answer);\n      // Later calls in this step are judged knowing this one came first.\n      history.push({ [call.name]: \"(earlier call in this step)\" });\n    }\n    return answers;\n  }\n\n  async evaluate(event: Record<string, any>): Promise<Verdict> {\n    const started = Date.now();\n    const base = { event_id: randomUUID(), provider: PROVIDER };\n    const session = String(event.session_hint ?? event.connection ?? event.agent_id ?? \"\");\n    if (event.kind === \"step/request\") {\n      const messages = event.payload?.messages ?? event.payload?.input;\n      const entries = entriesFromMessages(messages);\n      if (entries.length > 0) this.remember(session, entries);\n      return { ...base, decision: \"allow\", latency_ms: Date.now() - started };\n    }\n\n    const calls = callsIn(String(event.llm_protocol ?? \"canonical\"), event.payload);\n    const history = this.sessions.get(session) ?? [];\n    const answers = await this.judgeCalls(calls, history, String(event.agent_type ?? \"\"), session);\n    this.remember(session, history);\n    const findings: Finding[] = [];\n    const notices: string[] = [];\n    const paths: string[] = [];\n    const unjudged: string[] = [];\n    answers.forEach((answer, i) => {\n      const call = calls[i]!;\n      if (answer.unjudged) unjudged.push(call.path);\n      if (answer.refused) {\n        const { category, severity, detector, notice } = answer.refused;\n        findings.push({ category, severity, path: call.path, detector, subject: call.name });\n        paths.push(call.path);\n        notices.push(notice);\n      }\n    });\n\n    return {\n      ...base,\n      decision: findings.length > 0 ? \"block\" : \"allow\",\n      latency_ms: Date.now() - started,\n      ...(findings.length > 0 ? { findings, continuation: { style: \"drop_calls\" as const, paths, notice: notices.join(\" \") } } : {}),\n      ...(unjudged.length > 0 ? { unjudged } : {}),\n    };\n  }\n}\n\nconst readJson = (req: IncomingMessage): Promise<any> =>\n  new Promise((resolve, reject) => {\n    const parts: Buffer[] = [];\n    req.on(\"data\", (part: Buffer) => parts.push(part));\n    req.on(\"end\", () => {\n      try {\n        resolve(JSON.parse(Buffer.concat(parts).toString(\"utf8\") || \"{}\"));\n      } catch (error) {\n        reject(error);\n      }\n    });\n    req.on(\"error\", reject);\n  });\n\nconst send = (res: ServerResponse, status: number, value: unknown, headers: Record<string, string> = {}) => {\n  res.writeHead(status, { \"content-type\": \"application/json\", ...headers });\n  res.end(JSON.stringify(value));\n};\n\n/** Answers the Runtime API's paths. Returns false for any other path. */\nexport async function handleRuntime(runtime: LocalRuntime, req: IncomingMessage, res: ServerResponse, pathname: string): Promise<boolean> {\n  if (pathname === \"/v1/evaluate\" && req.method === \"POST\") {\n    let event: Record<string, any>;\n    try {\n      event = await readJson(req);\n    } catch {\n      send(res, 400, { error: { message: \"the body is not JSON\" } });\n      return true;\n    }\n    send(res, 200, await runtime.evaluate(event));\n    return true;\n  }\n  if (pathname === \"/v1/rules\" && req.method === \"GET\") {\n    const ruleset = loadRuleset();\n    if (req.headers[\"if-none-match\"]?.includes(ruleset.id)) {\n      res.writeHead(304).end();\n      return true;\n    }\n    send(res, 200, { ruleset }, { etag: `\"${ruleset.id}\"` });\n    return true;\n  }\n  if (pathname === \"/v1/heartbeat\" && req.method === \"POST\") {\n    await readJson(req).catch(() => ({}));\n    send(res, 200, { rules: { id: loadRuleset().id } });\n    return true;\n  }\n  if (pathname === \"/v1/limits\" && req.method === \"GET\") {\n    send(res, 200, {});\n    return true;\n  }\n  return false;\n}\n"
    }
  ],
